<?php
declare(strict_types=1);
namespace App\Modules\Identity\Controllers;
use App\Http\Controllers\Controller;
use App\Models\User;
use App\Modules\Identity\Services\IdentitySecurity as Security;
use App\Modules\Identity\Services\Outbox;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Crypt;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
use Illuminate\Validation\Rules\Password;
use PragmaRX\Google2FA\Google2FA;
class SecurityController extends Controller {
 public function forgot(Request $r){$d=$r->validate(['email'=>['required','email','max:254']]);$u=User::where('email',strtolower(trim($d['email'])))->where('is_active',true)->first();if($u)Security::email($u,'reset');return response()->json(['message'=>'Si le compte existe, un lien temporaire sera préparé.']);}
 public function reset(Request $r){$d=$r->validate(['token'=>['required','string','size:64'],'password'=>['required','confirmed',Password::min(12)->letters()->numbers(),'max:128'],'mfa_code'=>['nullable','string','max:32']]);Security::consume($d['token'],'reset',function($u)use($d){if($u->mfa_confirmed_at)Security::mfa($u,$d['mfa_code']??null);$u->forceFill(['password'=>$d['password'],'remember_token'=>null])->save();$u->tokens()->delete();DB::table('identity_tokens')->where('user_id',$u->id)->whereNull('consumed_at')->update(['consumed_at'=>now()]);});return response()->json(['message'=>'Mot de passe renouvelé. Reconnectez-vous.']);}
 public function requestVerification(Request $r){if(!$r->user()->email_verified_at)Security::email($r->user());return response()->json(['message'=>'La demande de vérification a été enregistrée. Consultez les notifications pour l’état d’envoi.']);}
 public function verify(Request $r){$d=$r->validate(['token'=>['required','string','size:64'],'purpose'=>['required','in:verify,email_change']]);Security::consume($d['token'],$d['purpose'],function($u,$ctx)use($d){if($d['purpose']==='email_change'){abort_unless($u->pending_email===$ctx['email'],422,'Changement devenu invalide.');abort_if(User::where('email',$ctx['email'])->where('id','!=',$u->id)->exists(),422,'Adresse indisponible.');$u->forceFill(['email'=>$ctx['email'],'pending_email'=>null,'email_verified_at'=>now()])->save();$u->tokens()->delete();}else{abort_unless($u->email===$ctx['email'],422,'Lien devenu invalide.');$u->forceFill(['email_verified_at'=>now()])->save();}});return response()->json(['message'=>'Adresse vérifiée.']);}
 private function password(Request $r):User{$u=$r->user();abort_unless(is_string($r->input('current_password'))&&Hash::check($r->input('current_password'),$u->password),422,'Vérification du mot de passe échouée.');return $u;}
 public function changePassword(Request $r){$d=$r->validate(['password'=>['required','confirmed',Password::min(12)->letters()->numbers(),'max:128']]);$this->password($r);DB::transaction(function()use($r,$d){$u=User::lockForUpdate()->findOrFail($r->user()->id);$this->passwordFor($r,$u);if($u->mfa_confirmed_at)Security::mfa($u,$r->input('mfa_code'));$u->forceFill(['password'=>$d['password'],'remember_token'=>null])->save();$u->tokens()->delete();DB::table('identity_tokens')->where('user_id',$u->id)->whereNull('consumed_at')->update(['consumed_at'=>now()]);});return response()->json(['message'=>'Mot de passe changé. Toutes les sessions sont révoquées.']);}
 private function passwordFor(Request $r,User $u):void{abort_unless(is_string($r->input('current_password'))&&strlen($r->input('current_password'))<=512&&Hash::check($r->input('current_password'),$u->password),422,'Vérification du mot de passe échouée.');}
 public function changeEmail(Request $r){$d=$r->validate(['email'=>['required','email','max:254']]);DB::transaction(function()use($r,$d){$u=User::lockForUpdate()->findOrFail($r->user()->id);$this->passwordFor($r,$u);if($u->mfa_confirmed_at)Security::mfa($u,$r->input('mfa_code'));$email=strtolower(trim($d['email']));abort_if(User::where('email',$email)->exists(),422,'Adresse indisponible.');$u->forceFill(['pending_email'=>$email])->save();Security::email($u,'email_change',$email);});return response()->json(['message'=>'Changement en attente de vérification de la nouvelle adresse.']);}
 public function status(Request $r){return response()->json(['mfa_required'=>\App\Modules\Identity\Services\MfaPolicy::required($r->user()),'mfa_enabled'=>(bool)$r->user()->mfa_confirmed_at,'recovery_codes_remaining'=>DB::table('mfa_recovery_codes')->where('user_id',$r->user()->id)->whereNull('used_at')->count(),'pending_email'=>$r->user()->pending_email,'google_linked'=>DB::table('auth_identities')->where('user_id',$r->user()->id)->where('provider','google')->exists(),'local_inbox'=>Outbox::localInbox()]);}
 public function setupMfa(Request $r){$this->password($r);$secret=(new Google2FA())->generateSecretKey();DB::transaction(function()use($r,$secret){$u=User::lockForUpdate()->findOrFail($r->user()->id);$this->passwordFor($r,$u);abort_if($u->mfa_confirmed_at,409,'MFA déjà actif.');$u->forceFill(['mfa_secret'=>Crypt::encryptString($secret),'mfa_last_step'=>null])->save();});return response()->json(['secret'=>$secret,'uri'=>(new Google2FA())->getQRCodeUrl('BestPharma',$r->user()->email,$secret)])->header('Cache-Control','no-store');}
 public function confirmMfa(Request $r){DB::transaction(function()use($r){$u=User::lockForUpdate()->findOrFail($r->user()->id);abort_unless($u->mfa_secret&&!$u->mfa_confirmed_at,409);Security::mfa($u,$r->input('mfa_code'));$u->forceFill(['mfa_confirmed_at'=>now()])->save();$u->tokens()->delete();});return response()->json(['message'=>'MFA activé. Reconnectez-vous avec votre code.']);}
 public function disableMfa(Request $r){abort_if(\App\Modules\Identity\Services\MfaPolicy::required($r->user()),403,'Le MFA est obligatoire pour vos fonctions. Utilisez vos codes de secours en cas de perte.');DB::transaction(function()use($r){$u=User::lockForUpdate()->findOrFail($r->user()->id);$this->passwordFor($r,$u);abort_unless($u->mfa_confirmed_at,409);Security::mfa($u,$r->input('mfa_code'));DB::table('mfa_recovery_codes')->where('user_id',$u->id)->delete();$u->forceFill(['mfa_secret'=>null,'mfa_confirmed_at'=>null,'mfa_last_step'=>null])->save();$u->tokens()->delete();});return response()->json(['message'=>'MFA désactivé. Reconnectez-vous.']);}
 public function recoveryCodes(Request $r){
  $codes=DB::transaction(function()use($r){$u=User::lockForUpdate()->findOrFail($r->user()->id);$this->passwordFor($r,$u);abort_unless($u->is_active&&$u->mfa_confirmed_at,409,'MFA non actif.');Security::mfa($u,$r->input('mfa_code'));DB::table('mfa_recovery_codes')->where('user_id',$u->id)->delete();$codes=[];for($i=0;$i<10;$i++){$code=bin2hex(random_bytes(16));$codes[]=$code;DB::table('mfa_recovery_codes')->insert(['user_id'=>$u->id,'code_hash'=>hash('sha256',$code),'created_at'=>now(),'updated_at'=>now()]);}Outbox::push($u->id,'mfa-recovery-rotated:'.bin2hex(random_bytes(12)),'Codes de secours renouvelés','Les anciens codes sont invalides. Conservez les nouveaux codes hors de votre compte.');return $codes;});
  return response()->json(['codes'=>$codes])->header('Cache-Control','no-store');
 }
 public function sessions(Request $r){return response()->json(['data'=>$r->user()->tokens()->orderByDesc('id')->get(['id','name','last_used_at','expires_at','created_at'])]);}
 public function revokeSession(Request $r,string $id){$r->user()->tokens()->where('id',$id)->firstOrFail()->delete();return response()->json(['message'=>'Session révoquée.']);}
 public function notifications(Request $r){$d=$r->validate(['status'=>['nullable','in:pending,sent,failed,simulated'],'page'=>['sometimes','integer','min:1']]);$q=DB::table('notification_outbox')->where('user_id',$r->user()->id);if(!empty($d['status']))$q->where('status',$d['status']);$rows=$q->latest('id')->paginate(25,['id','title','status','attempts','retry_at','created_at','read_at']);$data=$rows->toArray();$data['local_inbox']=Outbox::localInbox();return response()->json($data)->header('Cache-Control','no-store');}
 public function read(Request $r,string $id){$n=DB::table('notification_outbox')->where('id',$id)->where('user_id',$r->user()->id)->first();abort_unless($n,404);DB::table('notification_outbox')->where('id',$n->id)->update(['read_at'=>now()]);return response()->json(['message'=>'Notification lue.']);}
 public function retry(Request $r,string $id){DB::transaction(function()use($r,$id){$n=DB::table('notification_outbox')->where('id',$id)->where('user_id',$r->user()->id)->lockForUpdate()->first();abort_unless($n,404);abort_unless($n->status==='failed'&&$n->attempts<5,409,'Ce message ne peut plus être relancé. Préparez un nouveau lien si nécessaire.');DB::table('notification_outbox')->where('id',$n->id)->update(['retry_at'=>now(),'updated_at'=>now()]);});return response()->json(['message'=>'Nouvelle tentative planifiée, sans confirmation d’envoi.']);}
 public function preview(Request $r,string $id){abort_unless(Outbox::localInbox(),404);$n=DB::table('notification_outbox')->where('id',$id)->where('user_id',$r->user()->id)->first();abort_unless($n,404);$data=json_decode(Crypt::decryptString($n->encrypted_message),true);return response()->json(['message'=>$data['body'],'simulation'=>true])->header('Cache-Control','no-store');}
}
